import * as T from '../vendor/three.module.js';
import {createValley} from './landscape.js?v=2';
import {groundHeight,walkHeight,canWalk,riverX,riverWidth,clamp,cottage,bridge} from './terrain.js?v=2';

const $=id=>document.getElementById(id),keys=new Set(),coarse=matchMedia('(pointer:coarse)').matches;
let renderer,scene,camera,valley,sun,entered=false,lightweight=coarse,yaw=0,pitch=0,drag=null,dragLength=0,touchLook=null,touchMove={x:0,y:0},jump=0,vertical=0,time=0,last=performance.now(),frame=0,transition=null,activeView='creek',toastTimer,audio=null;
const player=new T.Vector3(17,0,35),eyeHeight=1.72,lookTarget=new T.Vector3();
const stoneX=riverX(31)+riverWidth(31)+1.1,stoneY=groundHeight(stoneX,31);
const views={
  creek:{position:[25,11,48],target:[-7,6,-14],spawn:[bridge.x+11,bridge.z],look:[bridge.x-12,bridge.y+1.72,bridge.z],name:'溪畔小径',note:'桥的那边，有一座等风的小屋。'},
  cottage:{position:[-5,8,7],target:[-19,6.7,-19],spawn:[-15,-5],look:[-19,5.7,-19],name:'林间小屋',note:'木窗、花箱与炊烟，收留一个慢下来的下午。'},
  flowers:{position:[42,11,32],target:[18,8,-18],spawn:[29,10],look:[24,7,-11],name:'风中花坡',note:'花顺着山坡开，风从树林那边来。'},
  stones:{position:[stoneX-5.8,Math.max(groundHeight(stoneX-5.8,35.5)+2.2,2.65),35.5],target:[stoneX,stoneY+.63,31],spawn:[stoneX+3.5,35.5],look:[stoneX,stoneY+.7,31],name:'青苔石岸',note:'溪水浸过岩缝，青苔在朝阴的一面生长。'}
};
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200)}
function setOrientation(target){let d=new T.Vector3(...target).sub(camera.position);yaw=Math.atan2(-d.x,-d.z);pitch=Math.atan2(d.y,Math.hypot(d.x,d.z));camera.rotation.set(pitch,yaw,0,'YXZ')}
function transitionCamera(position,target){document.querySelector('.locations').setAttribute('aria-busy','true');transition={from:camera.position.clone(),to:new T.Vector3(...position),lookFrom:lookTarget.clone(),lookTo:new T.Vector3(...target),start:performance.now()};}
function chooseView(name){if(!views[name])return;activeView=name;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);b.setAttribute('aria-pressed',String(b.dataset.view===name))});$('place').textContent=views[name].name;$('placeNote').textContent=views[name].note;if(entered){const v=views[name];player.set(v.spawn[0],walkHeight(...v.spawn)+eyeHeight,v.spawn[1]);camera.position.copy(player);jump=0;vertical=0;setOrientation(v.look);keys.clear();toast('已来到'+v.name)}else transitionCamera(views[name].position,views[name].target)}
function enter(){if(!valley)return;entered=true;const v=views[activeView];player.set(v.spawn[0],walkHeight(...v.spawn)+eyeHeight,v.spawn[1]);camera.position.copy(player);transition=null;document.querySelector('.locations').setAttribute('aria-busy','false');setOrientation(v.look);$('welcome').classList.add('leaving');setTimeout(()=>$('welcome').hidden=true,550);$('crosshair').hidden=false;$('walkHud').hidden=false;$('touch').hidden=!coarse;renderer.domElement.focus();toast(coarse?'左侧摇杆行走 · 右侧拖动环顾':'WASD 行走 · 按住鼠标拖动环顾 · 走上小桥过溪');}
function overview(){entered=false;keys.clear();document.exitPointerLock?.();$('welcome').hidden=false;$('welcome').classList.remove('leaving');$('walkHud').hidden=true;$('crosshair').hidden=true;$('touch').hidden=true;lookTarget.copy(camera.position).add(camera.getWorldDirection(new T.Vector3()).multiplyScalar(25));transitionCamera(views[activeView].position,views[activeView].target)}
function help(){const p=$('helpPanel');p.hidden=!p.hidden;keys.clear();if(!p.hidden)document.exitPointerLock?.();}
function savePhoto(){try{const visible=document.querySelectorAll('.topbar,.weather,.welcome,#walkHud,.minimap,footer');renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(!blob){toast('照片未能保存，请再试一次');return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='晴日山谷-'+new Date().toISOString().slice(0,10)+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已保存这一刻的晴天')},'image/png')}catch(e){toast('当前浏览器未能保存照片')}}
function sound(){if(audio){const muted=audio.gain.gain.value>.001;audio.gain.gain.setTargetAtTime(muted?0:.055,audio.ctx.currentTime,.5);$('sound').classList.toggle('active',!muted);$('sound').setAttribute('aria-label',muted?'开启溪水与微风声':'关闭自然声音');return}try{const Ctx=window.AudioContext||window.webkitAudioContext,ctx=new Ctx(),gain=ctx.createGain();gain.gain.value=.055;gain.connect(ctx.destination);const buffer=ctx.createBuffer(1,ctx.sampleRate*4,ctx.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){let white=Math.random()*2-1;last=(last+.035*white)/1.035;data[i]=last*5}const source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;let filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1100;source.connect(filter);filter.connect(gain);source.start();audio={ctx,gain};$('sound').classList.add('active');$('sound').setAttribute('aria-label','关闭自然声音');toast('溪水与微风声已开启')}catch{toast('此浏览器暂不支持自然音')}}
function installInput(){
  const canvas=renderer.domElement;canvas.tabIndex=0;canvas.setAttribute('aria-label','晴日山谷：WASD 移动，拖动鼠标环顾');
  addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'){$('helpPanel').hidden=true;keys.clear();return}if(e.repeat){keys.add(k);return}if(k==='h'){help();return}if(k==='p'){savePhoto();return}if(['1','2','3','4'].includes(k)){chooseView(['creek','cottage','flowers','stones'][Number(k)-1]);return}if(!entered||!$('helpPanel').hidden)return;keys.add(k);if(k===' '&&jump===0)vertical=5.0});
  addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();drag=null;touchLook=null;touchMove={x:0,y:0}});document.addEventListener('visibilitychange',()=>{keys.clear();last=performance.now()});
  canvas.addEventListener('pointerdown',e=>{if(!entered||!$('helpPanel').hidden)return;if(e.pointerType==='touch'){touchLook={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);return}if(e.button!==0)return;drag={x:e.clientX,y:e.clientY};dragLength=0;canvas.setPointerCapture(e.pointerId)});
  canvas.addEventListener('pointermove',e=>{if(!entered||!$('helpPanel').hidden)return;let dx=0,dy=0;if(touchLook?.id===e.pointerId){dx=e.clientX-touchLook.x;dy=e.clientY-touchLook.y;touchLook.x=e.clientX;touchLook.y=e.clientY}else if(document.pointerLockElement===canvas){dx=e.movementX;dy=e.movementY}else if(drag){dx=e.clientX-drag.x;dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;dragLength+=Math.abs(dx)+Math.abs(dy)}else return;yaw-=dx*.0024;pitch=clamp(pitch-dy*.0024,-1.28,1.25)});
  canvas.addEventListener('pointerup',e=>{if(touchLook?.id===e.pointerId)touchLook=null;if(drag&&dragLength<3&&e.pointerType!=='touch'){try{canvas.requestPointerLock()?.catch(()=>{})}catch{}}drag=null});canvas.addEventListener('pointercancel',()=>{drag=null;touchLook=null});canvas.addEventListener('contextmenu',e=>e.preventDefault());
  let joyId=null;const joy=$('joystick'),knob=joy.querySelector('i');function joyAt(e){let r=joy.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/36,y=(e.clientY-r.top-r.height/2)/36,n=Math.max(1,Math.hypot(x,y));touchMove={x:x/n,y:y/n};knob.style.transform=`translate(${x/n*29}px,${y/n*29}px)`}joy.addEventListener('pointerdown',e=>{joyId=e.pointerId;joy.setPointerCapture(e.pointerId);joyAt(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyId)joyAt(e)});function release(){joyId=null;touchMove={x:0,y:0};knob.style.transform=''}joy.addEventListener('pointerup',release);joy.addEventListener('pointercancel',release);$('jump').onclick=()=>{if(entered&&jump===0)vertical=5};
  addEventListener('resize',resize);$('enter').onclick=enter;$('overview').onclick=overview;$('help').onclick=help;$('helpPanel').querySelector('.close').onclick=help;$('photo').onclick=savePhoto;$('sound').onclick=sound;$('retry').onclick=()=>location.reload();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>chooseView(b.dataset.view));
  $('quality').onclick=()=>{lightweight=!lightweight;renderer.setPixelRatio(Math.min(devicePixelRatio,lightweight?1:1.75));valley.grass.count=lightweight?Math.min(14000,valley.grass.instanceMatrix.count):valley.grass.instanceMatrix.count;sun.shadow.mapSize.setScalar(lightweight?2048:4096);sun.shadow.map?.dispose();sun.shadow.map=null;renderer.shadowMap.needsUpdate=true;$('quality').textContent=lightweight?'轻盈 ◌':'细腻 ◉';toast(lightweight?'已切换轻盈画质':'已切换细腻画质')};
}
function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}
function move(dt){
  if(!$('helpPanel').hidden)return;
  let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0)-touchMove.y,side=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+touchMove.x,l=Math.hypot(forward,side);if(l>1){forward/=l;side/=l}let speed=keys.has('shift')?6.1:3.6,dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*side)*speed*dt,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*side)*speed*dt;
  const valid=(x,z)=>canWalk(x,z)&&!valley.trees.colliders.some(t=>Math.hypot(x-t.x,z-t.z)<t.r+.24);
  if(valid(player.x+dx,player.z))player.x+=dx;if(valid(player.x,player.z+dz))player.z+=dz;
  if(jump>0||vertical>0){vertical-=14*dt;jump=Math.max(0,jump+vertical*dt);if(jump===0)vertical=0}
  let bob=l>.05?Math.sin(time*(keys.has('shift')?11:7))*.022:0,target=walkHeight(player.x,player.z)+eyeHeight+jump+bob;player.y=T.MathUtils.lerp(player.y,target,1-Math.exp(-dt*16));camera.position.copy(player);camera.rotation.set(pitch,yaw,0,'YXZ');
  if(frame%50===0){let where=Math.hypot(player.x-stoneX,player.z-31)<9?'stones':Math.hypot(player.x+19,player.z+19)<15?'cottage':player.x>18&&player.z<25?'flowers':'creek';$('place').textContent=views[where].name;$('placeNote').textContent=views[where].note;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===where);b.setAttribute('aria-pressed',String(b.dataset.view===where))})}
}
function drawMap(){const c=$('map'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#e7edcf';ctx.fillRect(0,0,w,h);const project=(x,z)=>[w*.50+x*2.1,h*.50+z*1.65];ctx.fillStyle='#d0dfb7';for(let i=0;i<12;i++){let x=(i%4)*85+16,y=Math.floor(i/4)*78+12;ctx.beginPath();ctx.ellipse(x,y,36,23,i*.7,0,Math.PI*2);ctx.fill()}ctx.beginPath();for(let z=-100;z<110;z+=2){let [x,y]=project(riverX(z),z);z===-100?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.strokeStyle='#9ccfd0';ctx.lineWidth=12;ctx.stroke();ctx.strokeStyle='#c2decf';ctx.lineWidth=3;ctx.stroke();ctx.setLineDash([4,4]);ctx.beginPath();const route=[[-38,80],[-15,34],[bridge.x,bridge.z],[-19,-13]];route.forEach((p,i)=>{let [x,y]=project(...p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle='#bfaf75';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([]);let [hx,hy]=project(cottage.x,cottage.z);ctx.fillStyle='#ad7e62';ctx.fillRect(hx-6,hy-4,12,9);ctx.beginPath();ctx.moveTo(hx-9,hy-4);ctx.lineTo(hx,hy-12);ctx.lineTo(hx+9,hy-4);ctx.fill();ctx.fillStyle='#b1a0bc';for(let i=0;i<14;i++){let [fx,fy]=project(22+Math.sin(i*2)*10,-8+Math.cos(i*3)*14);ctx.beginPath();ctx.arc(fx,fy,2.6,0,Math.PI*2);ctx.fill()}let p=entered?player:camera.position,[px,py]=project(p.x,p.z);ctx.save();ctx.translate(px,py);ctx.rotate(entered?yaw:Math.atan2(camera.position.x-views[activeView].target[0],camera.position.z-views[activeView].target[2]));ctx.fillStyle='#b58b45';ctx.strokeStyle='#fff9df';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(-5,6);ctx.lineTo(0,3);ctx.lineTo(5,6);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-last)/1000,.045);last=now;if(document.hidden)return;time+=dt;frame++;if(entered)move(dt);else if(transition){let a=clamp((now-transition.start)/1200,0,1),s=a*a*(3-2*a);camera.position.lerpVectors(transition.from,transition.to,s);lookTarget.lerpVectors(transition.lookFrom,transition.lookTo,s);camera.lookAt(lookTarget);if(a===1){transition=null;document.querySelector('.locations').setAttribute('aria-busy','false')}}valley.update(time);if(frame%120===0)renderer.shadowMap.needsUpdate=true;renderer.render(scene,camera);if(frame%5===0)drawMap()}
async function init(){try{
  renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance',preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,lightweight?1:1.75));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.03;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;$('scene').appendChild(renderer.domElement);
  renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('failureMessage').textContent='图形资源暂时不足，请关闭其他三维页面后重新打开。';$('failure').hidden=false});
  scene=new T.Scene();scene.background=new T.Color('#b8dce9');scene.fog=new T.FogExp2('#bcd7e2',.00069);camera=new T.PerspectiveCamera(51,innerWidth/innerHeight,.12,2400);camera.position.fromArray(views.creek.position);lookTarget.fromArray(views.creek.target);camera.lookAt(lookTarget);
  const hemi=new T.HemisphereLight('#c8e1ee','#9a9e68',1.62);scene.add(hemi);sun=new T.DirectionalLight('#fff2d3',3.1);sun.position.set(-70,115,55);sun.target.position.set(-5,0,-20);sun.castShadow=true;sun.shadow.mapSize.setScalar(lightweight?2048:4096);Object.assign(sun.shadow.camera,{left:-110,right:110,top:110,bottom:-110,near:.5,far:320});sun.shadow.bias=-.00025;sun.shadow.normalBias=.045;sun.shadow.radius=2;scene.add(sun,sun.target);
  await new Promise(r=>requestAnimationFrame(r));valley=createValley(scene,{lightweight});renderer.shadowMap.needsUpdate=true;renderer.render(scene,camera);installInput();$('loading').hidden=true;$('enter').disabled=false;$('enterLabel').textContent='走进晴日山谷';if(lightweight)$('quality').textContent='轻盈 ◌';renderer.domElement.dataset.ready='true';const requested=new URLSearchParams(location.search).get('view');if(views[requested]){activeView=requested;camera.position.fromArray(views[requested].position);lookTarget.fromArray(views[requested].target);camera.lookAt(lookTarget);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===requested);b.setAttribute('aria-pressed',String(b.dataset.view===requested))})}last=performance.now();requestAnimationFrame(animate);console.info('Sunny Valley ready: '+valley.trees.count+' trees, '+valley.flowerCount+' flowers.');
}catch(error){console.error(error);$('loading').hidden=true;$('welcome').hidden=true;$('failureMessage').textContent='场景暂未能完整加载，请刷新后重试，并确认浏览器已开启图形加速。';$('failure').hidden=false}}
init();
